96	/**
97	 * Incremental state machine behind both parse() and createParser(). It reads
98	 * every character exactly once and keeps only the record in progress, so work
99	 * and memory are linear in the input no matter how it is chunked.
100	 */
101	class Parser {
102	  constructor({ delimiter, header, skipEmptyLines }) {
103	    this.delimiter = delimiter.charCodeAt(0);
104	    this.header = header;
105	    this.skipEmptyLines = skipEmptyLines;
106	
107	    this.state = FIELD_START;
108	    this.started = false; // whether a non-empty chunk has arrived (BOM check)
109	    this.offset = 0; // absolute offset of the next chunk, BOM excluded
110	    this.line = 1;
111	    this.lineStart = 0; // absolute offset of the current line's first character
112	    this.prevCR = false;
113	
114	    this.fields = []; // completed fields of the record in progress
115	    this.parts = []; // pieces of the field in progress
116	    this.recordStarted = false; // the record in progress has consumed a character
117	    this.recordLine = 1;
118	    this.fieldLine = 1; // where the field in progress starts
119	    this.fieldColumn = 1;
120	
121	    this.names = null; // header row, once read
122	    this.seenNames = header ? new Set() : null; // only while reading the header row
123	  }
