125	  write(chunk) {
126	    if (!this.started) {
127	      if (chunk.length === 0) return [];
128	      this.started = true;
129	      if (chunk.charCodeAt(0) === BOM) chunk = chunk.slice(1);
130	    }
131	
132	    const out = [];
133	    const base = this.offset;
134	    const delimiter = this.delimiter;
135	    const n = chunk.length;
136	    // Hot per-character state lives in locals and is stored back after the loop.
137	    let state = this.state;
138	    let line = this.line;
139	    let lineStart = this.lineStart;
140	    let prevCR = this.prevCR;
141	    let segmentStart = 0; // start of the unflushed field text in this chunk
142	
143	    for (let i = 0; i < n; i++) {
144	      const c = chunk.charCodeAt(i);
145	
146	      switch (state) {
147	        case FIELD_START:
148	          if (c === LF && prevCR) break; // rest of a CRLF that already ended the record
149	          if (!this.recordStarted) this.recordLine = line;
150	          this.fieldLine = line;
151	          this.fieldColumn = base + i - lineStart + 1;
152	          if (c === QUOTE) {
153	            this.recordStarted = true;
154	            state = QUOTED;
155	            segmentStart = i + 1;
156	          } else if (c === delimiter) {
157	            this.recordStarted = true;
158	            this.pushField('');
159	          } else if (c === CR || c === LF) {
