233	      case QUOTE_IN_QUOTED:
234	        this.pushField(this.takeField());
235	        this.endRecord(out);
236	        break;
237	      case FIELD_START:
238	        // Only a trailing delimiter leaves a started record here; a trailing
239	        // line break has already ended its record and starts no new one.
240	        if (this.recordStarted) {
241	          this.fieldLine = this.line;
242	          this.fieldColumn = this.offset - this.lineStart + 1;
243	          this.pushField('');
244	          this.endRecord(out);
245	        }
246	        break;
247	    }
248	    return out;
249	  }
250	
251	  takeField() {
252	    const parts = this.parts;
253	    const value = parts.length === 1 ? parts[0] : parts.join('');
254	    parts.length = 0;
255	    return value;
256	  }
257	
258	  pushField(value) {
259	    if (this.seenNames !== null) {
260	      if (this.seenNames.has(value)) {
261	        throw new CsvError(
262	          `Duplicate header name ${JSON.stringify(value)}`,
263	          this.fieldLine,
264	          this.fieldColumn,
265	        );
266	      }
267	      this.seenNames.add(value);
268	    }
269	    this.fields.push(value);
270	  }
271	
272	  endRecord(out) {
273	    const fields = this.fields;
274	    this.fields = [];
275	    this.recordStarted = false;
276	
277	    if (!this.header) {
278	      out.push(fields);
279	    } else if (this.names === null) {
280	      this.names = fields;
281	      this.seenNames = null;
282	    } else if (fields.length !== this.names.length) {
283	      throw new CsvError(
284	        `Expected ${this.names.length} fields to match the header but found ${fields.length}`,
285	        this.recordLine,
286	        1,
287	      );
288	    } else {
289	      out.push(toObject(this.names, fields));
290	    }
291	  }
292	}
