294	/**
295	 * Parses a complete CSV string.
296	 *
297	 * @param {string} text
298	 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
299	 * @returns {Array<string[]> | Array<Record<string, string>>} arrays of fields,
300	 *   or objects keyed by the first record when `header` is true.
301	 * @throws {TypeError} when `text` is not a string or an option is invalid.
302	 * @throws {CsvError} when the input is malformed.
303	 */
304	function parse(text, options = {}) {
305	  if (typeof text !== 'string') {
306	    throw new TypeError(`text must be a string; received ${describe(text)}`);
307	  }
308	  const parser = new Parser(readParseOptions(options));
309	  const records = parser.write(text);
310	  for (const record of parser.end()) records.push(record);
311	  return records;
312	}
313	
314	/**
315	 * Creates a parser for input that arrives in pieces. Chunks may split the
316	 * input anywhere; the combined output and errors match parse() on the whole.
317	 * Once end() has run or either method has thrown, both methods throw.
318	 *
319	 * @param {{delimiter?: string, header?: boolean, skipEmptyLines?: boolean}} [options]
320	 * @returns {{write(chunk: string): Array, end(): Array}}
321	 */
322	function createParser(options = {}) {
323	  const parser = new Parser(readParseOptions(options));
324	  let finished = false;
325	
326	  function run(step) {
327	    if (finished) {
328	      throw new Error('CSV parser is finished: end() was called or an earlier call threw');
329	    }
330	    try {
331	      return step();
332	    } catch (err) {
333	      finished = true;
334	      throw err;
335	    }
336	  }
337	
338	  return {
339	    write(chunk) {
340	      return run(() => {
341	        if (typeof chunk !== 'string') {
342	          throw new TypeError(`chunk must be a string; received ${describe(chunk)}`);
343	        }
344	        return parser.write(chunk);
345	      });
346	    },
347	    end() {
348	      const records = run(() => parser.end());
349	      finished = true;
350	      return records;
351	    },
352	  };
353	}
354	
355	function readStringifyOptions(options) {
356	  checkOptionsObject(options);
357	  const delimiter = readDelimiter(options.delimiter);
358	
359	  let eol = options.eol;
360	  if (eol === undefined) {
361	    eol = '\r\n';
362	  } else if (eol !== '\r\n' && eol !== '\n') {
363	    throw new TypeError(`eol must be '\\r\\n' or '\\n'; received ${describe(eol)}`);
364	  }
365	
366	  let header = options.header;
367	  if (header === undefined || header === false) {
368	    header = null;
369	  } else {
370	    // An indexed loop, unlike every(), also rejects holes in a sparse array.
371	    let valid = Array.isArray(header);
372	    for (let i = 0; valid && i < header.length; i++) valid = typeof header[i] === 'string';
373	    if (!valid) throw new TypeError('header must be an array of column name strings');
374	  }
375	
376	  return { delimiter, eol, header };
377	}
378	
379	function toText(value, row, field) {
380	  if (typeof value === 'string') return value;
381	  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
382	  if (value === null || value === undefined) return '';
383	  throw new TypeError(
384	    `row ${row}, field ${field}: expected a string, number, boolean, null or undefined; received ${describe(value)}`,
385	  );
386	}
387	
388	function needsQuotes(text, delimiter) {
389	  const last = text.length - 1;
390	  if (last < 0) return false;
391	  if (text.charCodeAt(0) === SPACE || text.charCodeAt(last) === SPACE) return true;
392	  for (let i = 0; i <= last; i++) {
393	    const c = text.charCodeAt(i);
394	    if (c === delimiter || c === QUOTE || c === CR || c === LF) return true;
395	  }
396	  return false;
397	}
398	
399	function encodeRecord(texts, delimiter, isFirst) {
400	  const delimiterCode = delimiter.charCodeAt(0);
401	  const encoded = new Array(texts.length);
402	  for (let i = 0; i < texts.length; i++) {
403	    const text = texts[i];
404	    encoded[i] = needsQuotes(text, delimiterCode) ? `"${text.replace(/"/g, '""')}"` : text;
405	  }
406	  // An unquoted lone empty field would be an empty line, which skipEmptyLines drops.
407	  if (encoded.length === 1 && encoded[0] === '') return '""';
408	
409	  const line = encoded.join(delimiter);
410	  // parse() drops a leading BOM, so the output must not start with a bare one.
411	  // The first field is unquoted here, so wrapping it needs no escaping.
412	  if (isFirst && line.charCodeAt(0) === BOM) {
413	    return `"${encoded[0]}"${line.slice(encoded[0].length)}`;
414	  }
415	  return line;
416	}
417	
418	/**
419	 * Serializes records to CSV text ending with one `eol`.
420	 *
421	 * @param {Array<Array<unknown>|Record<string, unknown>>} rows arrays of values;
422	 *   objects are also accepted when `options.header` is given.
423	 * @param {{delimiter?: string, eol?: '\r\n'|'\n', header?: string[]}} [options]
424	 * @returns {string}
425	 * @throws {TypeError} for invalid rows, values or options.
426	 */
427	function stringify(rows, options = {}) {
428	  if (!Array.isArray(rows)) {
429	    throw new TypeError(`rows must be an array; received ${describe(rows)}`);
430	  }
431	  const { delimiter, eol, header } = readStringifyOptions(options);
432	
433	  const lines = [];
434	  if (header !== null) lines.push(encodeRecord(header, delimiter, true));
435	
436	  for (let r = 0; r < rows.length; r++) {
437	    const row = rows[r];
438	    let texts;
439	    if (Array.isArray(row)) {
440	      texts = new Array(row.length);
441	      for (let i = 0; i < row.length; i++) texts[i] = toText(row[i], r, i);
442	    } else if (header !== null && row !== null && typeof row === 'object') {
443	      texts = new Array(header.length);
444	      for (let i = 0; i < header.length; i++) {
445	        const name = header[i];
446	        const value = Object.prototype.hasOwnProperty.call(row, name) ? row[name] : undefined;
447	        texts[i] = toText(value, r, i);
448	      }
449	    } else {
450	      const expected = header === null ? 'an array' : 'an array or an object';
451	      throw new TypeError(`row ${r} must be ${expected}; received ${describe(row)}`);
452	    }
453	    lines.push(encodeRecord(texts, delimiter, lines.length === 0));
454	  }
455	
456	  return lines.length === 0 ? '' : lines.join(eol) + eol;
457	}
458	
459	module.exports = { parse, createParser, stringify, CsvError };
